#!/bin/bash
awk '/<div id="add-patient-modal" class="modal">/{p=1} p && /<\/div>$/{p=0; print; print "\n    <!-- UPDATE PATIENT MODAL -->"; print "    <div id=\"update-patient-modal\" class=\"modal\">"; print "        <div class=\"modal-content\">"; print "            <span class=\"close\" id=\"close-up-modal\">&times;</span>"; print "            <h2>Update Patient Details</h2>"; print "            <form id=\"update-patient-form\">"; print "                <input type=\"hidden\" id=\"up-patient-id\">"; print "                <div class=\"form-group\">"; print "                    <label>Chief Complaint</label>"; print "                    <input type=\"text\" id=\"up-complaint\">"; print "                </div>"; print "                <div class=\"form-row\">"; print "                    <div class=\"form-group\">"; print "                        <label>Arrival Mode</label>"; print "                        <select id=\"up-arrival\">"; print "                            <option value=\"walk-in\">Walk-in</option>"; print "                            <option value=\"ambulance\">Ambulance</option>"; print "                            <option value=\"helicopter\">Helicopter</option>"; print "                        </select>"; print "                    </div>"; print "                    <div class=\"form-group\">"; print "                        <label>History Available</label>"; print "                        <select id=\"up-history\">"; print "                            <option value=\"false\">No</option>"; print "                            <option value=\"true\">Yes</option>"; print "                        </select>"; print "                    </div>"; print "                </div>"; print "                <div class=\"form-group\">"; print "                    <label>Medical History (comma-separated)</label>"; print "                    <input type=\"text\" id=\"up-med-history\">"; print "                </div>"; print "                <div class=\"form-group\">"; print "                    <label>Observed Signs (comma-separated)</label>"; print "                    <input type=\"text\" id=\"up-signs\">"; print "                </div>"; print "                <button type=\"submit\" class=\"btn-primary\" style=\"width:100%;margin-top:15px;\">Update Patient</button>"; print "            </form>"; print "        </div>"; print "    </div>"; next} 1' frontend/index.html > frontend/index.html.tmp
mv frontend/index.html.tmp frontend/index.html
